// escreva o filter aqui

exercises.solution:
const produtos = ['Banana prata', 'Maçã gala', 'banana nanica', 'Uva Itália', 'BANANA DA TERRA'];
const busca = 'BaNaNa';

const termo = busca.toLowerCase();
const achados = produtos.filter((produto) => produto.toLowerCase().includes(termo));

console.log(`Achados: ${achados.length}`);
console.log(achados);

